def chain_chain_chain_chain(WELL_FORMED):
    chain = []
    for token in WELL_FORMED:
        chain.append(token)

    def next_token(current_token, chain):
        if current_token == 'a':
            return 'b'
        elif current_token == 'b':
            return 'c'
        elif current_token == 'c':
            return 'd'
        else:
            return 'e'

    current_token = 'a'
    while True:
        next_token = next_token(current_token, chain)
        if next_token == 'a':
            break
        current_token = next_token

    return chain

